Lời giải triển khai một hệ thống quản lý công việc sử dụng thư viện `dataclass` để đảm bảo an toàn và dễ mở rộng. Hệ thống hỗ trợ thêm/xóa/sửa thông tin công việc, kiểm tra ID hợp lệ và trả về mã trạng thái HTTP 404 khi không tìm thấy.

```python
from dataclasses import dataclass, field

class TodoItem(dataclass(field)):
    id: str
    text: str
    completed: bool = False

@dataclass
class TodoSystem:
    todos: list[TodoItem] = []

    def add_todo(self, text: str, completed: bool=False) -> None:
        self.todos.append(TodoItem(text, completed))

    def view_all(self) -> list[TodoItem]:
        return [item for item in self.todos if item.completed]

    def edit_status(self, text: str) -> None:
        for item in self.todos:
            if item.text == text:
                item.completed = True
                return

        raise ValueError("Todo not found")

    def delete_todo(self, id: str) -> None:
        for item in self.todos:
            if item.id == id:
                self.todos.remove(item)
                return
        raise ValueError("Todo not found")

def create_todo(text: str) -> TodoItem:
        return TodoItem(text, True)

# Testing the system
todos = []
for _ in range(10):
        todo = create_todo("Task #%d" % (random.randint(1, 999)))
        todos.append(todo)

response = f"{'success': 'Tasks added successfully'}"
print(response)

try:
        todos[0].completed = True
    except ValueError as e:
        print(e)
    response = f"{'success': 'Task #0 not found'}"

print(response)
```
